(function() {
  'use strict';
  
  window.Alpine = {
    data: function(name, callback) {
      if (typeof name === 'string') {
        this._components = this._components || {};
        this._components[name] = callback;
      }
    },
    
    start: function() {
      this._started = true;
      this._initComponents();
    },
    
    _components: {},
    _started: false,
    
    _initComponents: function() {
      document.querySelectorAll('[x-data]').forEach(el => {
        const dataAttr = el.getAttribute('x-data');
        const componentName = dataAttr.replace(/\(\).*/, '');
        
        if (this._components[componentName]) {
          const component = this._components[componentName]();
          el._x_data = component;
          
          // Initialize
          if (component.init) {
            component.init();
          }
          
          // Handle x-show
          this._handleShow(el, component);
          
          // Handle x-text
          this._handleText(el, component);
          
          // Handle clicks
          this._handleClicks(el, component);
          
          // Handle templates
          this._handleTemplates(el, component);
        }
      });
    },
    
    _handleShow: function(root, component) {
      root.querySelectorAll('[x-show]').forEach(el => {
        const expr = el.getAttribute('x-show');
        const show = this._evaluate(expr, component);
        el.style.display = show ? '' : 'none';
      });
    },
    
    _handleText: function(root, component) {
      root.querySelectorAll('[x-text]').forEach(el => {
        const expr = el.getAttribute('x-text');
        el.textContent = this._evaluate(expr, component);
      });
    },
    
    _handleClicks: function(root, component) {
      root.querySelectorAll('[\\@click]').forEach(el => {
        const expr = el.getAttribute('@click');
        el.addEventListener('click', () => {
          this._execute(expr, component);
          this._refresh(root, component);
        });
      });
    },
    
    _handleTemplates: function(root, component) {
      root.querySelectorAll('template[x-for]').forEach(template => {
        const forExpr = template.getAttribute('x-for');
        const match = forExpr.match(/(\w+)\s+in\s+(.+)/);
        if (match) {
          const itemName = match[1];
          const arrayExpr = match[2];
          const array = this._evaluate(arrayExpr, component);
          
          if (Array.isArray(array)) {
            const fragment = document.createDocumentFragment();
            array.forEach(item => {
              const clone = template.content.cloneNode(true);
              const itemData = { ...component, [itemName]: item };
              this._processNode(clone, itemData);
              fragment.appendChild(clone);
            });
            template.parentNode.insertBefore(fragment, template.nextSibling);
          }
        }
      });
    },
    
    _processNode: function(node, data) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        // Handle :src
        if (node.hasAttribute(':src')) {
          const expr = node.getAttribute(':src');
          node.src = this._evaluate(expr, data);
        }
        
        // Handle :alt
        if (node.hasAttribute(':alt')) {
          const expr = node.getAttribute(':alt');
          node.alt = this._evaluate(expr, data);
        }
        
        // Handle x-text
        if (node.hasAttribute('x-text')) {
          const expr = node.getAttribute('x-text');
          node.textContent = this._evaluate(expr, data);
        }
        
        // Handle @click
        if (node.hasAttribute('@click')) {
          const expr = node.getAttribute('@click');
          node.addEventListener('click', () => {
            this._execute(expr, data);
          });
        }
        
        // Process children
        node.childNodes.forEach(child => this._processNode(child, data));
      }
    },
    
    _evaluate: function(expr, data) {
      try {
        const func = new Function(...Object.keys(data), `return ${expr}`);
        return func(...Object.values(data));
      } catch (e) {
        console.error('Error evaluating expression:', expr, e);
        return '';
      }
    },
    
    _execute: function(expr, data) {
      try {
        const func = new Function(...Object.keys(data), expr);
        func(...Object.values(data));
      } catch (e) {
        console.error('Error executing expression:', expr, e);
      }
    },
    
    _refresh: function(root, component) {
      this._handleShow(root, component);
      this._handleText(root, component);
    }
  };
  
  // Auto-start Alpine when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => Alpine.start());
  } else {
    Alpine.start();
  }
  
  // Dispatch alpine:init event
  document.dispatchEvent(new CustomEvent('alpine:init'));
})();
